const fs = require('fs');
const pdf = require('pdf-parse');
const XLSX = require('xlsx');
const { parse } = require('csv-parse/sync');
const levenshtein = require('fast-levenshtein');

const VENDOR_FILE = '/root/vendors.xlsx';
const PO_FILE = '/root/purchase_orders.csv';
const INVOICE_FILE = '/root/invoices.pdf';
const OUTPUT_FILE = '/root/fraud_report.json';

// Helper to normalize vendor names for comparison
function normalizeName(name) {
    if (!name) return '';
    let s = name.toLowerCase();
    s = s.replace(/\blimited\b/g, 'ltd');
    s = s.replace(/\bincorporated\b/g, 'inc');
    s = s.replace(/\bcorporation\b/g, 'corp');
    s = s.replace(/[^a-z0-9]/g, ''); // Remove all non-alphanumeric
    return s;
}

async function main() {
    // 1. Load Vendors
    const workbook = XLSX.readFile(VENDOR_FILE);
    const sheet = workbook.Sheets[workbook.SheetNames[0]];
    const vendorsRaw = XLSX.utils.sheet_to_json(sheet);

    // Normalize keys (handle potential case differences in header)
    const vendors = vendorsRaw.map(v => {
        const keys = Object.keys(v);
        const getKey = (sub) => keys.find(k => k.toLowerCase().includes(sub));
        return {
            id: v[getKey('id')],
            name: v[getKey('name')],
            iban: v[getKey('iban')],
            normName: normalizeName(v[getKey('name')])
        };
    });

    // 2. Load POs
    const poContent = fs.readFileSync(PO_FILE);
    const posRaw = parse(poContent, { columns: true, skip_empty_lines: true });

    const pos = {};
    posRaw.forEach(p => {
        const keys = Object.keys(p);
        const getKey = (sub) => keys.find(k => k.toLowerCase().replace(/_/g, '').includes(sub));
        const poNum = p[getKey('po')];
        if (poNum) {
            pos[poNum] = {
                amount: parseFloat(p[getKey('amount')]),
                vendorId: p[getKey('vendor')] // Make sure checks CSV header "Vendor ID" or similar
            };
        }
    });

    // 3. Process PDF
    const dataBuffer = fs.readFileSync(INVOICE_FILE);
    const pageTexts = [];

    await pdf(dataBuffer, {
        pagerender: function(pageData) {
            return pageData.getTextContent().then(textContent => {
                let text = '';
                let lastY = null;
                for (let item of textContent.items) {
                    if (lastY !== item.transform[5] && lastY !== null) {
                        text += '\n';
                    }
                    text += item.str;
                    lastY = item.transform[5];
                }
                pageTexts.push(text);
                return text;
            });
        }
    });

    const flaggedInvoices = [];

    pageTexts.forEach((text, index) => {
        const pageNum = index + 1;

        // Extract Fields
        const lines = text.split('\n');

        // Default values
        let vendorName = null;
        let amount = null;
        let iban = null;
        let poNumber = null;

        // Simple Regex extraction based on observed format
        // From: Vendor 11
        // Total $8623.76
        // Payment IBAN: FRADULENT_IBAN
        // PO Number: PO-1030

        lines.forEach(line => {
            const l = line.trim();
            if (l.startsWith('From:')) vendorName = l.substring(5).trim();
            else if (l.startsWith('Total $')) amount = parseFloat(l.substring(7).trim());
            else if (l.startsWith('Payment IBAN:')) iban = l.substring(13).trim();
            else if (l.startsWith('PO Number:')) poNumber = l.substring(10).trim();
        });

        // Validation Logic
        let reason = null;
        let matchedVendor = null;

        // 1. Identify Vendor (Fuzzy Match)
        if (vendorName) {
            const normInput = normalizeName(vendorName);
            let bestMatch = null;
            let minDist = Infinity;

            vendors.forEach(v => {
                const dist = levenshtein.get(normInput, v.normName);
                if (dist < minDist) {
                    minDist = dist;
                    bestMatch = v;
                }
            });

            // Threshold: If normalized strings are very close.
            // Length dependent? 
            // If length is small (e.g. < 5), allow 0 or 1.
            // If length is larger, allow 2 or 3.
            // Let's use a conservative absolute threshold of 3 for now, 
            // given normalization handles "Ltd" etc.
            if (minDist <= 3) {
                matchedVendor = bestMatch;
            }
        }

        if (!matchedVendor) {
            reason = "Unknown Vendor";
        } else {
            // 2. IBAN Mismatch
            // Normalize IBANs (remove spaces)
            const inputIBAN = (iban || '').replace(/\s/g, '');
            const vendorIBAN = (matchedVendor.iban || '').replace(/\s/g, '');

            if (inputIBAN !== vendorIBAN) {
                reason = "IBAN Mismatch";
            } else {
                // 3. Invalid PO
                // If PO is "PO-INVALID" or null, it's not in keys.
                // Note: keys in `pos` are strings.
                if (!poNumber || !pos[poNumber]) {
                    reason = "Invalid PO";
                } else {
                    const poData = pos[poNumber];

                    // 4. Amount Mismatch
                    // > 0.01 difference
                    if (Math.abs(poData.amount - amount) > 0.01) {
                        reason = "Amount Mismatch";
                    } else {
                        // 5. Vendor Mismatch
                        // PO is linked to different Vendor ID
                        if (String(poData.vendorId) !== String(matchedVendor.id)) {
                            reason = "Vendor Mismatch";
                        }
                    }
                }
            }
        }

        if (reason) {
            flaggedInvoices.push({
                invoice_page_number: pageNum,
                vendor_name: vendorName,
                invoice_amount: amount,
                iban: iban,
                po_number: poNumber || null,
                reason: reason
            });
        }
    });

    fs.writeFileSync(OUTPUT_FILE, JSON.stringify(flaggedInvoices, null, 2));
    console.log(`Report generated with ${flaggedInvoices.length} entries.`);
}

main().catch(err => console.error(err));
